function CPS_decode_random_CPS_number_question_correct_answer_correct_answer_2_answer_message (random_number: number, question: string, correct_answer: string, correct_answer_2: string, correct_answer_message: string) {
    if (mobile == 0) {
        if (Random_CPS == random_number) {
            if (!(info.score() >= 150)) {
                game.splash("This costs 150 clicks")
            } else {
                game.splash("Do you trust this?", question)
                if (game.askForString("Do you trust this?", 3) == correct_answer || game.askForString("Do you trust this?", 3) == correct_answer_2) {
                    CPS += 1
                    info.setScore(info.score() - 150)
                    game.splash(correct_answer_message, "Your CPS increased by one.")
                } else {
                    info.setScore(info.score() - 150)
                    game.splash("Oh No you got it wrong", "But you already payed")
                }
            }
        }
    } else {
        if (Random_CPS == random_number) {
            if (!(info.score() >= 150)) {
                game.splash("This costs 150 clicks")
            } else {
                game.splash("Do you trust this?", question)
                if (game.askForString("Do you trust this?", 3, true) == correct_answer || game.askForString("Do you trust this?", 3, true) == correct_answer_2) {
                    CPS += 1
                    info.setScore(info.score() - 150)
                    game.splash(correct_answer_message, "Your CPS increased by one.")
                } else {
                    info.setScore(info.score() - 150)
                    game.splash("Oh No you got it wrong", "But you already payed")
                }
            }
        }
    }
}
